// ensuring determinism regardless of insertion order.
pub fn root(self) -> Result<B256, StateRootError> {
    match self.calculate(false)? {
        StateRootProgress::Complete(root, _, _) => Ok(root),
        StateRootProgress::Progress(..) => unreachable!(),
    }
}
// The calculate function walks hashed entries in sorted key order via TrieWalker,
// ensuring deterministic root computation.

